-- ============================================================
-- CINEVERSE - MYSQL 8 
-- ============================================================
-- Base autocontenida para el backend PHP actual.
--
-- Tablas activas:
--   users
--   reviews
--   login_attempts
--
-- Datos sinteticos de demostracion:
--   5.000 usuarios
--   24.322 resenas
--
-- Contraseña de todos los usuarios: password
--
-- Auditoria del corpus de comentarios:
--   24.322 comentarios completos distintos
--   0 duplicados exactos
--   mezcla de comentarios cortos, medios y largos
--   sin las frases roboticas detectadas en versiones anteriores
-- ============================================================

SET NAMES utf8mb4;
SET SQL_MODE = 'STRICT_TRANS_TABLES,NO_ZERO_DATE,NO_ZERO_IN_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';

CREATE DATABASE IF NOT EXISTS `cineverse`
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_0900_ai_ci;

USE `cineverse`;

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `reviews`;
DROP TABLE IF EXISTS `login_attempts`;

-- Limpieza de tablas heredadas que ya no usa CineVerse PHP puro.
DROP TABLE IF EXISTS `sessions`;
DROP TABLE IF EXISTS `personal_access_tokens`;
DROP TABLE IF EXISTS `password_reset_tokens`;
DROP TABLE IF EXISTS `job_batches`;
DROP TABLE IF EXISTS `jobs`;
DROP TABLE IF EXISTS `failed_jobs`;
DROP TABLE IF EXISTS `cache_locks`;
DROP TABLE IF EXISTS `cache`;
DROP TABLE IF EXISTS `migrations`;

DROP TABLE IF EXISTS `users`;

CREATE TABLE `users` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `username` VARCHAR(20) NOT NULL,
  `email` VARCHAR(80) NOT NULL,
  `password_hash` VARCHAR(255) NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `is_verified` TINYINT(1) NOT NULL DEFAULT 0,
  `verification_token` VARCHAR(255) DEFAULT NULL,
  `verification_expires_at` DATETIME DEFAULT NULL,
  `password_reset_token` VARCHAR(255) DEFAULT NULL,
  `password_reset_expires_at` DATETIME DEFAULT NULL,

  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_users_username` (`username`),
  UNIQUE KEY `uq_users_email` (`email`),
  UNIQUE KEY `uq_users_verification_token` (`verification_token`),
  UNIQUE KEY `uq_users_password_reset_token` (`password_reset_token`),

  CONSTRAINT `chk_users_is_verified`
    CHECK (`is_verified` IN (0, 1))
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `login_attempts` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `ip` VARCHAR(45) NOT NULL,
  `email` VARCHAR(80) NOT NULL,
  `attempts` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  `last_attempt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
    ON UPDATE CURRENT_TIMESTAMP,

  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_login_attempts_ip_email` (`ip`, `email`),
  KEY `idx_login_attempts_last_attempt` (`last_attempt`)
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `reviews` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` INT UNSIGNED NOT NULL,
  `movie_id` INT UNSIGNED NOT NULL,
  `movie_title` VARCHAR(255) NOT NULL,
  `rating` TINYINT UNSIGNED NOT NULL,
  `comment` TEXT NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
    ON UPDATE CURRENT_TIMESTAMP,

  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_reviews_user_movie` (`user_id`, `movie_id`),
  KEY `idx_reviews_movie_created` (`movie_id`, `created_at`),
  KEY `idx_reviews_user_created` (`user_id`, `created_at`),

  CONSTRAINT `fk_reviews_user`
    FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
    ON DELETE CASCADE,

  CONSTRAINT `chk_reviews_rating`
    CHECK (`rating` BETWEEN 1 AND 5),

  CONSTRAINT `chk_reviews_comment_length`
    CHECK (CHAR_LENGTH(`comment`) BETWEEN 20 AND 1000)
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_0900_ai_ci;

SET FOREIGN_KEY_CHECKS = 1;

START TRANSACTION;























































































































ALTER TABLE `users` AUTO_INCREMENT = 5001;
ALTER TABLE `reviews` AUTO_INCREMENT = 24323;

COMMIT;

